B.ba8=new A.br("prophets","Stories of the Prophets","Peace be upon them all")
B.bau=new A.br("women","Women of Islam","The hearts that carried the light")
B.b9T=new A.br("seerah","The Seerah","The life of the Prophet \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645")
